def _context(batch_id: str, kind: str) -> dict:
    return {
        "batch_id": batch_id,
        "kind": kind,
        "method": "default",
        "request_basis": "none",
        **dict.fromkeys(_ZERO_FIELDS, 0),
        **dict.fromkeys(_BOOL_FIELDS, False),
        **dict.fromkeys(_DATE_FIELDS, date(1900, 1, 1)),
